:host(.chapter-scope) {
  display: block;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #1a1a1a);
  background: var(--paper, #f9f9f9);
  padding: 2rem;
  line-height: 1.6;
}

.section-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--line, #e0e0e0);
  padding-bottom: 1rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--ink, #1a1a1a);
  margin: 0 0 0.5rem 0;
}

.section-takeaway {
  font-size: 1rem;
  color: var(--muted, #666);
  max-width: 800px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.main-visual {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.diagram-container {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  overflow: hidden;
  height: 300px;
}

#geo-diagram {
  width: 100%;
  height: 100%;
}

.formula-block {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-left: 4px solid var(--accent, #00CED1);
  padding: 1rem;
  border-radius: 4px;
}

.formula-label {
  font-size: 0.875rem;
  color: var(--muted, #666);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.math-display {
  font-family: 'Times New Roman', serif;
  font-size: 1.25rem;
  text-align: center;
  padding: 0.5rem 0;
  color: var(--ink, #1a1a1a);
}

.formula-note {
  font-size: 0.875rem;
  color: var(--muted, #666);
  margin-top: 0.5rem;
  text-align: center;
}

.interactive-panel {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.control-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--ink, #1a1a1a);
}

select, input[type="range"] {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  font-size: 0.875rem;
}

.status-box {
  background: var(--paper, #f9f9f9);
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  padding: 1rem;
  min-height: 80px;
}

.status-box h3 {
  font-size: 0.875rem;
  margin: 0 0 0.5rem 0;
  color: var(--muted, #666);
}

#status-text {
  font-size: 0.875rem;
  color: var(--ink, #1a1a1a);
  margin-bottom: 0.5rem;
}

.mono-text {
  font-family: monospace;
  font-size: 0.75rem;
  color: var(--accent, #00CED1);
  word-break: break-all;
}

.action-group {
  display: flex;
  gap: 0.5rem;
}

.primary-btn, .secondary-btn {
  padding: 0.75rem 1rem;
  border: none;
  border-radius: 4px;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.primary-btn {
  background: var(--accent, #00CED1);
  color: #fff;
  flex: 1;
}

.primary-btn:hover {
  background: #00b5b5;
}

.secondary-btn {
  background: var(--line, #e0e0e0);
  color: var(--ink, #1a1a1a);
}

.secondary-btn:hover {
  background: #d0d0d0;
}

.evidence-section {
  margin-top: 2rem;
}

.evidence-section h3 {
  font-size: 1.125rem;
  margin-bottom: 1rem;
  color: var(--ink, #1a1a1a);
}

.evidence-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1rem;
}

.evidence-card {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.card-header {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--accent, #00CED1);
  text-transform: uppercase;
}

.card-body {
  font-size: 0.875rem;
  color: var(--ink, #1a1a1a);
  flex: 1;
}

.source-btn {
  align-self: flex-start;
  background: transparent;
  border: 1px solid var(--line, #e0e0e0);
  color: var(--muted, #666);
  font-size: 0.75rem;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  cursor: pointer;
}

.source-btn:hover {
  border-color: var(--accent, #00CED1);
  color: var(--accent, #00CED1);
}

javascript:
(function() {
  const root = document.currentScript.closest('.chapter-scope');
  if (!root) return;

  const modeSelect = root.querySelector('#mode-select');
  const rangeSlider = root.querySelector('#range-slider');
  const rangeVal = root.querySelector('#range-val');
  const statusText = root.querySelector('#status-text');
  const matrixInfo = root.querySelector('#matrix-info');
  const calcBtn = root.querySelector('#calc-btn');
  const resetBtn = root.querySelector('#reset-btn');
  const svg = root.querySelector('#geo-diagram');
  const sensorsGroup = root.querySelector('#sensors-group');
  const sourceGroup = root.querySelector('#source-group');
  const hyperbolasGroup = root.querySelector('#hyperbolas-group');

  const sensors = [
    {x: 50, y: 50}, {x: 150, y: 50}, {x: 250, y: 50},
    {x: 50, y: 150}, {x: 150, y: 150}, {x: 250, y: 150}
  ];

  let sourceX = 200;
  let sourceY = 100;

  function drawSensors() {
    sensorsGroup.innerHTML = '';
    sensors.forEach((s, i) => {
      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', s.x);
      circle.setAttribute('cy', s.y);
      circle.setAttribute('r', 6);
      circle.setAttribute('fill', '#FFBF00');
      circle.setAttribute('stroke', '#1a1a1a');
      circle.setAttribute('stroke-width', 1);
      const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      text.setAttribute('x', s.x + 10);
      text.setAttribute('y', s.y + 4);
      text.setAttribute('font-size', '10');
      text.setAttribute('fill', '#666');
      text.textContent = `S${i+1}`;
      sensorsGroup.appendChild(circle);
      sensorsGroup.appendChild(text);
    });
  }

  function drawSource() {
    sourceGroup.innerHTML = '';
    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.setAttribute('cx', sourceX);
    circle.setAttribute('cy', sourceY);
    circle.setAttribute('r', 8);
    circle.setAttribute('fill', '#00CED1');
    circle.setAttribute('stroke', '#1a1a1a');
    circle.setAttribute('stroke-width', 2);
    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('x', sourceX + 12);
    text.setAttribute('y', sourceY + 4);
    text.setAttribute('font-size', '12');
    text.setAttribute('fill', '#00CED1');
    text.setAttribute('font-weight', 'bold');
    text.textContent = 'Source';
    sourceGroup.appendChild(circle);
    sourceGroup.appendChild(text);
  }

  function drawHyperbolas() {
    hyperbolasGroup.innerHTML = '';
    const refSensor = sensors[0];
    const refDist = Math.sqrt((sourceX - refSensor.x)**2 + (sourceY - refSensor.y)**2);

    sensors.slice(1).forEach((s, i) => {
      const dist = Math.sqrt((sourceX - s.x)**2 + (sourceY - s.y)**2);
      const diff = dist - refDist;

      if (Math.abs(diff) < 1e-6) {
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        const midX = (refSensor.x + s.x) / 2;
        const midY = (refSensor.y + s.y) / 2;
        const angle = Math.atan2(s.y - refSensor.y, s.x - refSensor.x);
        const perpAngle = angle + Math.PI / 2;
        const length = 200;
        line.setAttribute('x1', midX - length * Math.cos(perpAngle));
        line.setAttribute('y1', midY - length * Math.sin(perpAngle));
        line.setAttribute('x2', midX + length * Math.cos(perpAngle));
        line.setAttribute('y2', midY + length * Math.sin(perpAngle));
        line.setAttribute('stroke', '#00CED1');
        line.setAttribute('stroke-width', 1);
        line.setAttribute('stroke-dasharray', '4,4');
        line.setAttribute('opacity', '0.6');
        hyperbolasGroup.appendChild(line);
      } else {
        const a = Math.abs(diff) / 2;
        const c = Math.sqrt((refSensor.x - s.x)**2 + (refSensor.y - s.y)**2) / 2;
        if (c > a) {
          const b = Math.sqrt(c*c - a*a);
          const midX = (refSensor.x + s.x) / 2;
          const midY = (refSensor.y + s.y) / 2;
          const angle = Math.atan2(s.y - refSensor.y, s.x - refSensor.x);

          const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          let d = '';
          for (let t = -2; t <= 2; t += 0.1) {
            const x = a * Math.cosh(t);
            const y = b * Math.sinh(t);
            const rotX = x * Math.cos(angle) - y * Math.sin(angle) + midX;
            const rotY = x * Math.sin(angle) + y * Math.cos(angle) + midY;
            if (t === -2) {
              d += `M ${rotX} ${rotY}`;
            } else {
              d += ` L ${rotX} ${rotY}`;
            }
          }
          path.setAttribute('d', d);
          path.setAttribute('stroke', '#00CED1');
          path.setAttribute('stroke-width', 1);
          path.setAttribute('fill', 'none');
          path.setAttribute('opacity', '0.4');
          hyperbolasGroup.appendChild(path);
        }
      }
    });
  }

  function updateVisualization() {
    drawSensors();
    drawSource();
    drawHyperbolas();
  }

  function updateStatus() {
    const mode = modeSelect.value;
    const range = parseInt(rangeSlider.value, 10);
    rangeVal.textContent = range;

    if (mode === 'far') {
      statusText.textContent = '远场模式：权重矩阵简化为单位阵 (B ≈ r₀I)';
      matrixInfo.textContent = 'Ψ ≈ c²r₀²Q (标量缩放不影响解)';
      sourceY = 50;
    } else {
      statusText.textContent = '近场模式：需先估算 B 再修正';
      matrixInfo.textContent = 'Ψ = c²BQB (B 含未知 rᵢ⁰)';
      sourceY = 100 + (200 - range);
    }
    sourceX = 200;
    updateVisualization();
  }

  function calculate() {
    const mode = modeSelect.value;
    const range = parseInt(rangeSlider.value, 10);

    if (mode === 'far') {
      statusText.textContent = '计算完成：使用 Eq. 14b 直接求解';
      matrixInfo.textContent = `z_a ≈ (G_a^T Q^{-1} G_a)^{-1} G_a^T Q^{-1} h`;
    } else {
      statusText.textContent = '计算完成：先 Eq. 14b 估算 B，再 Eq. 14a 修正';
      matrixInfo.textContent = `Step 1: z_a^(0) via Eq. 14b\nStep 2: Estimate B from z_a^(0)\nStep 3: z_a via Eq. 14a`;
    }
  }

  function reset() {
    modeSelect.value = 'far';
    rangeSlider.value = 50;
    updateStatus();
    statusText.textContent = '等待输入...';
    matrixInfo.textContent = '';
  }

  modeSelect.addEventListener('change', updateStatus);
  rangeSlider.addEventListener('input', updateStatus);
  calcBtn.addEventListener('click', calculate);
  resetBtn.addEventListener('click', reset);

  updateVisualization();
  updateStatus();
})();
